<section><h1><?=$service?'Manage':'Offer'?> Custom Designs</h1><?php foreach($errors as $e):?><p class="alert error"><?=H::e($e)?></p><?php endforeach?><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?=H::csrf()?>"><label>Title<input name="title" required value="<?=H::e($_POST['title']??$service['title']??'')?>"></label><label>Description<textarea name="description" required><?=H::e($_POST['description']??$service['description']??'')?></textarea></label><label>Price<input type="number" min=".50" step=".01" name="price" required value="<?=H::e($_POST['price']??$service['price']??'')?>"></label><label>Expected turnaround (days)<input type="number" min="1" max="365" name="turnaround_days" required value="<?=H::e($_POST['turnaround_days']??$service['turnaround_days']??'')?>"></label><label>Included revisions<input type="number" min="0" max="100" name="included_revisions" value="<?=H::e($_POST['included_revisions']??$service['included_revisions']??0)?>"></label><label>Buyer instructions<textarea name="buyer_instructions"><?=H::e($_POST['buyer_instructions']??$service['buyer_instructions']??'')?></textarea></label><h2>Buyer questions</h2><div id="questions"><?php $rows=$questions?:[['question_text'=>'','is_required'=>0]];foreach($rows as $i=>$q):?><fieldset><label>Question <input name="questions[<?=$i?>]" value="<?=H::e($q['question_text'])?>"></label><label><input type="checkbox" name="question_required[<?=$i?>]" value="1" <?=$q['is_required']?'checked':''?>> Required</label></fieldset><?php endforeach?></div><button type="button" id="add-question">Add question</button><?php if($images):?><h2>Existing examples</h2><?php foreach($images as $image):?><label><img class="product-preview" src="<?=H::e($image['image_path'])?>" alt=""><input type="checkbox" name="remove_images[]" value="<?=$image['id']?>"> Remove</label><?php endforeach?><?php endif?><label>Add example images<input type="file" name="examples[]" multiple accept="image/jpeg,image/png,image/webp"></label><label><input type="checkbox" name="is_active" value="1" <?=!$service||$service['is_active']?'checked':''?>> Active and available</label><button>Save service</button></form></section><script>document.getElementById('add-question').addEventListener('click',function(){const box=document.getElementById('questions'),i=box.children.length,f=document.createElement('fieldset');f.innerHTML='<label>Question <input name="questions['+i+']"></label><label><input type="checkbox" name="question_required['+i+']" value="1"> Required</label>';box.appendChild(f);});</script>
